const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function rayBox(o,d,min,max){let lo=0,hi=1000;for(let i=0;i<3;i++){if(Math.abs(d[i])<1e-8){if(o[i]<min[i]||o[i]>max[i])return Infinity;}else{let a=(min[i]-o[i])/d[i],b=(max[i]-o[i])/d[i];if(a>b)[a,b]=[b,a];lo=Math.max(lo,a);hi=Math.min(hi,b);if(hi<lo)return Infinity;}}return lo;}
export function blocked(map,x,z,r=.32){return MAPS[map].boxes.some(b=>x+r>b.x-b.w/2&&x-r<b.x+b.w/2&&z+r>b.z-b.d/2&&z-r<b.z+b.d/2);}
