 loadout(id,data){const p=this.players.get(id);if(!p)return;const l={...p.loadout};if(W[data.primary]&&!['Pistols','Utility','Melee'].includes(W[data.primary].category))l.primary=data.primary;if(W[data.secondary]?.category==='Pistols')l.secondary=data.secondary;if(W[data.utility]?.category==='Utility')l.utility=data.utility;p.loadout=l;if(p.hp>0){for(const wid of Object.values(l))if(!p.inventory[wid])p.inventory[wid]={ammo:W[wid].mag,reserve:W[wid].mag*8};this.switchWeapon(p,l.primary);}this.emit('loadout',{id});}
