 scores(){if(MODES[this.settings.mode].teams)return[1,2].map(t=>({id:t,name:t===1?'Task Force':'Insurgents',score:[...this.players.values()].filter(p=>p.team===t).reduce((s,p)=>s+p.kills,0)})).sort((a,b)=>b.score-a.score);return[...this.players.values()].map(p=>({id:p.id,name:p.name,score:p.kills})).sort((a,b)=>b.score-a.score);}
 configure(s){const next=sanitizeSettings(s,this.settings);if(this.players.size>MODES[next.mode].limit)throw Error('Remove players before switching to a smaller mode.');this.settings=next;this.restart(true);}
